mod common;
use common::*;

type Enc = unsafe extern "C" fn(
    *mut u8,   // c
    *mut u64,  // clen_p
    *const u8, // m
    u64,       // mlen
    *const u8, // ad
    u64,       // adlen
    *const u8, // nsec
    *const u8, // npub
    *const u8, // k
) -> i32;

type Dec = unsafe extern "C" fn(
    *mut u8,   // m
    *mut u64,  // mlen_p
    *mut u8,   // nsec
    *const u8, // c
    u64,       // clen
    *const u8, // ad
    u64,       // adlen
    *const u8, // npub
    *const u8, // k
) -> i32;

type EncDet = unsafe extern "C" fn(
    *mut u8,   // c
    *mut u8,   // mac
    *mut u64,  // maclen_p
    *const u8, // m
    u64,       // mlen
    *const u8, // ad
    u64,       // adlen
    *const u8, // nsec
    *const u8, // npub
    *const u8, // k
) -> i32;

type DecDet = unsafe extern "C" fn(
    *mut u8,   // m
    *mut u8,   // nsec
    *const u8, // c
    u64,       // clen
    *const u8, // mac
    *const u8, // ad
    u64,       // adlen
    *const u8, // npub
    *const u8, // k
) -> i32;

type Keygen = unsafe extern "C" fn(*mut u8);

/// The five *available* AEAD primitives.
const AEADS: &[&str] = &[
    "crypto_aead_aegis128l",
    "crypto_aead_aegis256",
    "crypto_aead_chacha20poly1305",
    "crypto_aead_chacha20poly1305_ietf",
    "crypto_aead_xchacha20poly1305_ietf",
];

struct Sizes {
    kb: usize,
    nb: usize,
    ab: usize,
    nsb: usize,
    max: u64,
}

fn sizes(p: &str) -> Sizes {
    let g = |s: &str| -> usize {
        unsafe { sym::<unsafe extern "C" fn() -> usize>(c_lib(), &format!("{p}_{s}"))() }
    };
    let gm = || -> u64 {
        unsafe { sym::<unsafe extern "C" fn() -> u64>(c_lib(), &format!("{p}_messagebytes_max"))() }
    };
    Sizes {
        kb: g("keybytes"),
        nb: g("npubbytes"),
        ab: g("abytes"),
        nsb: g("nsecbytes"),
        max: gm(),
    }
}

/// Message lengths: per-primitive block boundaries (16/32/64), poly1305 pad
/// boundaries, and the 128 KiB `STREAM_POLY1305_CHUNK` restart boundary.
const MLENS: &[usize] = &[
    0, 1, 2, 15, 16, 17, 31, 32, 33, 47, 48, 63, 64, 65, 95, 96, 127, 128, 129, 255, 256, 257, 511,
    512, 1000, 4097,
];
/// AD lengths: absorb2 (2×RATE), absorb (RATE) and padded-tail shapes.
const ADLENS: &[usize] = &[0, 1, 8, 15, 16, 17, 31, 32, 33, 63, 64, 65, 100, 128, 200];
/// Lengths around the 131072-byte chunk restart (slow — used sparingly).
const CHUNK_LENS: &[usize] = &[131071, 131072, 131073, 131136, 200000, 262144];

// ---------------------------------------------------------------------------
// combined encrypt / decrypt round trip over the message-length axis
// ---------------------------------------------------------------------------

#[test]
fn aead_combined_message_lengths() {
    setup();
    let mut rng = Rng::new(0x8000);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        for &mlen in MLENS {
            for &adlen in &[0usize, 16, 100] {
                let k = rng.bytes(s.kb);
                let npub = rng.bytes(s.nb);
                let m = rng.bytes(mlen);
                let ad = rng.bytes(adlen);
                let clen_max = mlen + s.ab;

                let mut c1 = canary(clen_max);
                let mut c2 = canary(clen_max);
                let mut l1 = 0u64;
                let mut l2 = 0u64;
                let (ra, rb) = unsafe {
                    (
                        ce(
                            c1.as_mut_ptr(),
                            &mut l1,
                            m.as_ptr(),
                            mlen as u64,
                            ad.as_ptr(),
                            adlen as u64,
                            std::ptr::null(),
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                        re(
                            c2.as_mut_ptr(),
                            &mut l2,
                            m.as_ptr(),
                            mlen as u64,
                            ad.as_ptr(),
                            adlen as u64,
                            std::ptr::null(),
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                    )
                };
                eq_i32(&format!("{p}_encrypt rc(m={mlen},ad={adlen})"), ra, rb);
                eq_usize(
                    &format!("{p}_encrypt *clen_p(m={mlen},ad={adlen})"),
                    l1 as usize,
                    l2 as usize,
                );
                eq_bytes(&format!("{p}_encrypt(m={mlen},ad={adlen})"), &c1, &c2);
                assert_eq!(l1 as usize, clen_max);

                // decrypt the C-produced ciphertext with both
                let mut m1 = canary(mlen.max(1));
                let mut m2 = canary(mlen.max(1));
                let mut o1 = u64::MAX;
                let mut o2 = u64::MAX;
                let (ra, rb) = unsafe {
                    (
                        cd(
                            m1.as_mut_ptr(),
                            &mut o1,
                            std::ptr::null_mut(),
                            c1.as_ptr(),
                            l1,
                            ad.as_ptr(),
                            adlen as u64,
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                        rd(
                            m2.as_mut_ptr(),
                            &mut o2,
                            std::ptr::null_mut(),
                            c1.as_ptr(),
                            l1,
                            ad.as_ptr(),
                            adlen as u64,
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                    )
                };
                eq_i32(&format!("{p}_decrypt rc(m={mlen},ad={adlen})"), ra, rb);
                eq_usize(
                    &format!("{p}_decrypt *mlen_p(m={mlen},ad={adlen})"),
                    o1 as usize,
                    o2 as usize,
                );
                eq_bytes(&format!("{p}_decrypt(m={mlen},ad={adlen})"), &m1, &m2);
                assert_eq!(ra, 0, "{p} round trip must succeed");
                assert_eq!(&m1[..mlen], &m[..], "{p} round trip plaintext");
            }
        }
    }
}

#[test]
fn aead_combined_ad_lengths() {
    setup();
    let mut rng = Rng::new(0x8001);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        for &adlen in ADLENS {
            for &mlen in &[0usize, 1, 32, 64, 100] {
                let k = rng.bytes(s.kb);
                let npub = rng.bytes(s.nb);
                let m = rng.bytes(mlen);
                let ad = rng.bytes(adlen);
                let mut c1 = canary(mlen + s.ab);
                let mut c2 = canary(mlen + s.ab);
                let (ra, rb) = unsafe {
                    (
                        ce(
                            c1.as_mut_ptr(),
                            std::ptr::null_mut(),
                            m.as_ptr(),
                            mlen as u64,
                            ad.as_ptr(),
                            adlen as u64,
                            std::ptr::null(),
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                        re(
                            c2.as_mut_ptr(),
                            std::ptr::null_mut(),
                            m.as_ptr(),
                            mlen as u64,
                            ad.as_ptr(),
                            adlen as u64,
                            std::ptr::null(),
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                    )
                };
                eq_i32(&format!("{p}_encrypt rc(ad={adlen})"), ra, rb);
                eq_bytes(&format!("{p}_encrypt(ad={adlen},m={mlen})"), &c1, &c2);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// detached API, and combined-vs-detached equivalence
// ---------------------------------------------------------------------------

#[test]
fn aead_detached_and_equivalence() {
    setup();
    let mut rng = Rng::new(0x8002);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, _) = pair::<Enc>(&format!("{p}_encrypt"));
        let (ced, red) = pair::<EncDet>(&format!("{p}_encrypt_detached"));
        let (cdd, rdd) = pair::<DecDet>(&format!("{p}_decrypt_detached"));
        for &mlen in &[0usize, 1, 5, 15, 16, 17, 31, 32, 33, 63, 64, 65, 128, 1000, 4097] {
            for &adlen in &[0usize, 1, 16, 17, 100] {
                let k = rng.bytes(s.kb);
                let npub = rng.bytes(s.nb);
                let m = rng.bytes(mlen);
                let ad = rng.bytes(adlen);

                let mut c1 = canary(mlen.max(1));
                let mut c2 = canary(mlen.max(1));
                let mut t1 = canary(s.ab);
                let mut t2 = canary(s.ab);
                let mut ml1 = u64::MAX;
                let mut ml2 = u64::MAX;
                let (ra, rb) = unsafe {
                    (
                        ced(
                            c1.as_mut_ptr(),
                            t1.as_mut_ptr(),
                            &mut ml1,
                            m.as_ptr(),
                            mlen as u64,
                            ad.as_ptr(),
                            adlen as u64,
                            std::ptr::null(),
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                        red(
                            c2.as_mut_ptr(),
                            t2.as_mut_ptr(),
                            &mut ml2,
                            m.as_ptr(),
                            mlen as u64,
                            ad.as_ptr(),
                            adlen as u64,
                            std::ptr::null(),
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                    )
                };
                eq_i32(&format!("{p}_encrypt_detached rc(m={mlen},ad={adlen})"), ra, rb);
                eq_usize(&format!("{p}_encrypt_detached *maclen_p"), ml1 as usize, ml2 as usize);
                eq_bytes(&format!("{p}_encrypt_detached c(m={mlen},ad={adlen})"), &c1, &c2);
                eq_bytes(&format!("{p}_encrypt_detached mac(m={mlen},ad={adlen})"), &t1, &t2);
                assert_eq!(ml1 as usize, s.ab);

                // combined output must equal detached c || mac
                let mut comb = canary(mlen + s.ab);
                unsafe {
                    ce(
                        comb.as_mut_ptr(),
                        std::ptr::null_mut(),
                        m.as_ptr(),
                        mlen as u64,
                        ad.as_ptr(),
                        adlen as u64,
                        std::ptr::null(),
                        npub.as_ptr(),
                        k.as_ptr(),
                    );
                }
                eq_bytes(
                    &format!("{p} combined==detached c(m={mlen},ad={adlen})"),
                    &comb[..mlen],
                    &c1[..mlen],
                );
                eq_bytes(
                    &format!("{p} combined==detached mac(m={mlen},ad={adlen})"),
                    &comb[mlen..],
                    &t1,
                );

                // decrypt_detached
                let mut p1 = canary(mlen.max(1));
                let mut p2 = canary(mlen.max(1));
                let (ra, rb) = unsafe {
                    (
                        cdd(
                            p1.as_mut_ptr(),
                            std::ptr::null_mut(),
                            c1.as_ptr(),
                            mlen as u64,
                            t1.as_ptr(),
                            ad.as_ptr(),
                            adlen as u64,
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                        rdd(
                            p2.as_mut_ptr(),
                            std::ptr::null_mut(),
                            c1.as_ptr(),
                            mlen as u64,
                            t1.as_ptr(),
                            ad.as_ptr(),
                            adlen as u64,
                            npub.as_ptr(),
                            k.as_ptr(),
                        ),
                    )
                };
                eq_i32(&format!("{p}_decrypt_detached rc(m={mlen},ad={adlen})"), ra, rb);
                eq_bytes(&format!("{p}_decrypt_detached(m={mlen},ad={adlen})"), &p1, &p2);
                assert_eq!(ra, 0);
                assert_eq!(&p1[..mlen], &m[..]);
            }
        }
    }
}

/// `maclen_p == NULL` (encrypt_detached) and `clen_p`/`mlen_p == NULL`.
#[test]
fn aead_null_out_length_pointers() {
    setup();
    let mut rng = Rng::new(0x8003);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        let (ced, red) = pair::<EncDet>(&format!("{p}_encrypt_detached"));
        for &mlen in &[0usize, 1, 64, 100, 1000] {
            let k = rng.bytes(s.kb);
            let npub = rng.bytes(s.nb);
            let m = rng.bytes(mlen);
            let ad = rng.bytes(16);

            // clen_p == NULL
            let mut c1 = canary(mlen + s.ab);
            let mut c2 = canary(mlen + s.ab);
            unsafe {
                let a = ce(
                    c1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    ad.as_ptr(),
                    16,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = re(
                    c2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    ad.as_ptr(),
                    16,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_encrypt clen_p=NULL rc"), a, b);
            }
            eq_bytes(&format!("{p}_encrypt clen_p=NULL(m={mlen})"), &c1, &c2);

            // mlen_p == NULL on decrypt
            let mut m1 = canary(mlen.max(1));
            let mut m2 = canary(mlen.max(1));
            unsafe {
                let a = cd(
                    m1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    ad.as_ptr(),
                    16,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = rd(
                    m2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    ad.as_ptr(),
                    16,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_decrypt mlen_p=NULL rc"), a, b);
                assert_eq!(a, 0);
            }
            eq_bytes(&format!("{p}_decrypt mlen_p=NULL(m={mlen})"), &m1, &m2);

            // maclen_p == NULL on encrypt_detached
            let mut d1 = canary(mlen.max(1));
            let mut d2 = canary(mlen.max(1));
            let mut t1 = canary(s.ab);
            let mut t2 = canary(s.ab);
            unsafe {
                let a = ced(
                    d1.as_mut_ptr(),
                    t1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    ad.as_ptr(),
                    16,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = red(
                    d2.as_mut_ptr(),
                    t2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    ad.as_ptr(),
                    16,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_encrypt_detached maclen_p=NULL rc"), a, b);
            }
            eq_bytes(&format!("{p} det maclen_p=NULL c"), &d1, &d2);
            eq_bytes(&format!("{p} det maclen_p=NULL mac"), &t1, &t2);
        }
    }
}

/// `m == NULL` on decrypt (verify-only mode) and `ad == NULL` with `adlen == 0`,
/// `m == NULL` with `mlen == 0` on encrypt, non-NULL `nsec` (must be ignored).
#[test]
fn aead_null_pointer_valid_shapes() {
    setup();
    let mut rng = Rng::new(0x8004);
    for &p in AEADS {
        let s = sizes(p);
        assert_eq!(s.nsb, 0, "{p}_nsecbytes must be 0");
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        for &mlen in &[0usize, 1, 64, 1000] {
            let k = rng.bytes(s.kb);
            let npub = rng.bytes(s.nb);
            let m = rng.bytes(mlen);
            let mut c1 = canary(mlen + s.ab);
            let mut c2 = canary(mlen + s.ab);

            // ad = NULL, adlen = 0
            unsafe {
                let a = ce(
                    c1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    if mlen == 0 { std::ptr::null() } else { m.as_ptr() },
                    mlen as u64,
                    std::ptr::null(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = re(
                    c2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    if mlen == 0 { std::ptr::null() } else { m.as_ptr() },
                    mlen as u64,
                    std::ptr::null(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_encrypt ad=NULL rc"), a, b);
            }
            eq_bytes(&format!("{p}_encrypt ad=NULL,m={mlen}"), &c1, &c2);

            // ad = NULL, adlen = 0 must equal a non-NULL ad with adlen = 0
            let ad0 = [0u8; 4];
            let mut c3 = canary(mlen + s.ab);
            unsafe {
                ce(
                    c3.as_mut_ptr(),
                    std::ptr::null_mut(),
                    if mlen == 0 { std::ptr::null() } else { m.as_ptr() },
                    mlen as u64,
                    ad0.as_ptr(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
            }
            eq_bytes(&format!("{p} ad=NULL == ad!=NULL,adlen=0"), &c1, &c3);

            // decrypt with m = NULL (verify only)
            let mut o1 = u64::MAX;
            let mut o2 = u64::MAX;
            unsafe {
                let a = cd(
                    std::ptr::null_mut(),
                    &mut o1,
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = rd(
                    std::ptr::null_mut(),
                    &mut o2,
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_decrypt m=NULL rc(m={mlen})"), a, b);
                assert_eq!(a, 0, "{p} verify-only must succeed");
            }
            eq_usize(&format!("{p}_decrypt m=NULL *mlen_p"), o1 as usize, o2 as usize);

            // non-NULL nsec must be ignored and left untouched
            let mut ns1 = [0xA5u8; 8];
            let mut ns2 = [0xA5u8; 8];
            let mut m1 = canary(mlen.max(1));
            let mut m2 = canary(mlen.max(1));
            unsafe {
                let a = cd(
                    m1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    ns1.as_mut_ptr(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = rd(
                    m2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    ns2.as_mut_ptr(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_decrypt nsec!=NULL rc"), a, b);
            }
            eq_bytes(&format!("{p} nsec buffer untouched"), &ns1, &ns2);
            assert_eq!(ns1, [0xA5u8; 8], "{p} must not write to nsec");
            eq_bytes(&format!("{p}_decrypt nsec!=NULL plaintext"), &m1, &m2);
        }
    }
}

/// In-place operation (`c == m`).
#[test]
fn aead_in_place() {
    setup();
    let mut rng = Rng::new(0x8005);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        for &mlen in &[0usize, 1, 16, 17, 32, 33, 64, 65, 1000] {
            let k = rng.bytes(s.kb);
            let npub = rng.bytes(s.nb);
            let m = rng.bytes(mlen);
            let ad = rng.bytes(16);

            let mut b1 = canary(mlen + s.ab);
            let mut b2 = canary(mlen + s.ab);
            b1[..mlen].copy_from_slice(&m);
            b2[..mlen].copy_from_slice(&m);
            unsafe {
                let a = ce(
                    b1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    b1.as_ptr(),
                    mlen as u64,
                    ad.as_ptr(),
                    16,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = re(
                    b2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    b2.as_ptr(),
                    mlen as u64,
                    ad.as_ptr(),
                    16,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_encrypt in-place rc"), a, b);
            }
            eq_bytes(&format!("{p}_encrypt in-place(m={mlen})"), &b1, &b2);

            // decrypt in place
            let mut d1 = b1.clone();
            let mut d2 = b1.clone();
            unsafe {
                let a = cd(
                    d1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    d1.as_ptr(),
                    (mlen + s.ab) as u64,
                    ad.as_ptr(),
                    16,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = rd(
                    d2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    d2.as_ptr(),
                    (mlen + s.ab) as u64,
                    ad.as_ptr(),
                    16,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_decrypt in-place rc"), a, b);
                assert_eq!(a, 0);
            }
            eq_bytes(&format!("{p}_decrypt in-place(m={mlen})"), &d1, &d2);
            assert_eq!(&d1[..mlen], &m[..]);
        }
    }
}

/// Degenerate / extreme key and nonce shapes.
#[test]
fn aead_key_nonce_shapes() {
    setup();
    let mut rng = Rng::new(0x8006);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        let mlen = 64usize;
        let adlen = 16usize;
        let m = rng.bytes(mlen);
        let ad = rng.bytes(adlen);
        let keys: Vec<Vec<u8>> = vec![vec![0u8; s.kb], vec![0xffu8; s.kb], rng.bytes(s.kb)];
        let mut nonces: Vec<Vec<u8>> = vec![vec![0u8; s.nb], vec![0xffu8; s.nb], rng.bytes(s.nb)];
        // For xchacha20: nonces differing only in the first / second half hit
        // structurally different dependencies (hchacha20 subkey vs npub2).
        if s.nb == 24 {
            let base = rng.bytes(24);
            let mut a = base.clone();
            a[3] ^= 0xff; // first half only
            let mut b = base.clone();
            b[20] ^= 0xff; // second half only
            nonces.push(base);
            nonces.push(a);
            nonces.push(b);
        }
        for k in &keys {
            for n in &nonces {
                let mut c1 = canary(mlen + s.ab);
                let mut c2 = canary(mlen + s.ab);
                unsafe {
                    let a = ce(
                        c1.as_mut_ptr(),
                        std::ptr::null_mut(),
                        m.as_ptr(),
                        mlen as u64,
                        ad.as_ptr(),
                        adlen as u64,
                        std::ptr::null(),
                        n.as_ptr(),
                        k.as_ptr(),
                    );
                    let b = re(
                        c2.as_mut_ptr(),
                        std::ptr::null_mut(),
                        m.as_ptr(),
                        mlen as u64,
                        ad.as_ptr(),
                        adlen as u64,
                        std::ptr::null(),
                        n.as_ptr(),
                        k.as_ptr(),
                    );
                    eq_i32(&format!("{p} key/nonce shape rc"), a, b);
                }
                eq_bytes(
                    &format!("{p}(k={}, n={})", hex(k), hex(n)),
                    &c1,
                    &c2,
                );
            }
        }
    }
}

/// The 128 KiB `STREAM_POLY1305_CHUNK` restart boundary of the three
/// poly1305-based AEADs (and the same lengths for AEGIS as a control).
#[test]
fn aead_chunk_boundary_lengths() {
    setup();
    let mut rng = Rng::new(0x8007);
    for &p in AEADS {
        let s = sizes(p);
        let (ce, re) = pair::<Enc>(&format!("{p}_encrypt"));
        let (cd, rd) = pair::<Dec>(&format!("{p}_decrypt"));
        for &mlen in CHUNK_LENS {
            let k = rng.bytes(s.kb);
            let npub = rng.bytes(s.nb);
            let m = rng.bytes(mlen);
            let mut c1 = vec![0xA5u8; mlen + s.ab];
            let mut c2 = vec![0xA5u8; mlen + s.ab];
            unsafe {
                let a = ce(
                    c1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    std::ptr::null(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = re(
                    c2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    std::ptr::null(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_encrypt chunk rc(m={mlen})"), a, b);
            }
            eq_bytes(&format!("{p}_encrypt chunk(m={mlen})"), &c1, &c2);

            // decrypt (single un-chunked pass in C) must agree with encrypt
            let mut d1 = vec![0xA5u8; mlen];
            let mut d2 = vec![0xA5u8; mlen];
            unsafe {
                let a = cd(
                    d1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = rd(
                    d2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    (mlen + s.ab) as u64,
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32(&format!("{p}_decrypt chunk rc(m={mlen})"), a, b);
                assert_eq!(a, 0, "{p} chunk round-trip");
            }
            eq_bytes(&format!("{p}_decrypt chunk(m={mlen})"), &d1, &d2);
            assert_eq!(d1, m);
        }
    }
}

/// AEGIS detached mode accepts `clen < ABYTES` (no gate) — a valid config.
#[test]
fn aegis_detached_short_clen() {
    setup();
    let mut rng = Rng::new(0x8008);
    for &p in &["crypto_aead_aegis128l", "crypto_aead_aegis256"] {
        let s = sizes(p);
        assert_eq!(s.ab, 32);
        let (ced, red) = pair::<EncDet>(&format!("{p}_encrypt_detached"));
        let (cdd, rdd) = pair::<DecDet>(&format!("{p}_decrypt_detached"));
        for &mlen in &[0usize, 1, 5, 31] {
            let k = rng.bytes(s.kb);
            let npub = rng.bytes(s.nb);
            let m = rng.bytes(mlen);
            let mut c1 = canary(mlen.max(1));
            let mut c2 = canary(mlen.max(1));
            let mut t1 = canary(s.ab);
            let mut t2 = canary(s.ab);
            unsafe {
                let a = ced(
                    c1.as_mut_ptr(),
                    t1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    std::ptr::null(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = red(
                    c2.as_mut_ptr(),
                    t2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    m.as_ptr(),
                    mlen as u64,
                    std::ptr::null(),
                    0,
                    std::ptr::null(),
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32("aegis det short rc", a, b);
            }
            eq_bytes(&format!("{p} det short c(m={mlen})"), &c1, &c2);
            eq_bytes(&format!("{p} det short mac(m={mlen})"), &t1, &t2);

            let mut p1 = canary(mlen.max(1));
            let mut p2 = canary(mlen.max(1));
            unsafe {
                let a = cdd(
                    p1.as_mut_ptr(),
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    mlen as u64,
                    t1.as_ptr(),
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                let b = rdd(
                    p2.as_mut_ptr(),
                    std::ptr::null_mut(),
                    c1.as_ptr(),
                    mlen as u64,
                    t1.as_ptr(),
                    std::ptr::null(),
                    0,
                    npub.as_ptr(),
                    k.as_ptr(),
                );
                eq_i32("aegis det short decrypt rc", a, b);
                assert_eq!(a, 0);
            }
            eq_bytes(&format!("{p} det short decrypt(m={mlen})"), &p1, &p2);
        }
    }
}

/// Cross-variant wiring: xchacha20poly1305_ietf(k, npub24) must equal
/// chacha20poly1305_ietf(hchacha20(npub[0..16], k), 0000||npub[16..24]).
#[test]
fn xchacha_equals_chacha_ietf_with_derived_subkey() {
    setup();
    let mut rng = Rng::new(0x8009);
    let (cx, _) = pair::<Enc>("crypto_aead_xchacha20poly1305_ietf_encrypt");
    let (ci, _) = pair::<Enc>("crypto_aead_chacha20poly1305_ietf_encrypt");
    // use the *Rust* library for both halves of the identity too
    let (_, rx) = pair::<Enc>("crypto_aead_xchacha20poly1305_ietf_encrypt");
    let (_, ri) = pair::<Enc>("crypto_aead_chacha20poly1305_ietf_encrypt");
    let hchacha =
        pair::<unsafe extern "C" fn(*mut u8, *const u8, *const u8, *const u8) -> i32>(
            "crypto_core_hchacha20",
        );
    for &mlen in &[0usize, 1, 64, 65, 1000] {
        for &adlen in &[0usize, 16, 17] {
            let k = rng.bytes(32);
            let npub = rng.bytes(24);
            let m = rng.bytes(mlen);
            let ad = rng.bytes(adlen);
            for (which, (xf, inf, hc)) in [(cx, ci, hchacha.0), (rx, ri, hchacha.1)]
                .into_iter()
                .enumerate()
            {
                let mut k2 = [0u8; 32];
                unsafe {
                    hc(
                        k2.as_mut_ptr(),
                        npub.as_ptr(),
                        k.as_ptr(),
                        std::ptr::null(),
                    )
                };
                let mut npub2 = [0u8; 12];
                npub2[4..].copy_from_slice(&npub[16..24]);

                let mut a = canary(mlen + 16);
                let mut b = canary(mlen + 16);
                unsafe {
                    xf(
                        a.as_mut_ptr(),
                        std::ptr::null_mut(),
                        m.as_ptr(),
                        mlen as u64,
                        ad.as_ptr(),
                        adlen as u64,
                        std::ptr::null(),
                        npub.as_ptr(),
                        k.as_ptr(),
                    );
                    inf(
                        b.as_mut_ptr(),
                        std::ptr::null_mut(),
                        m.as_ptr(),
                        mlen as u64,
                        ad.as_ptr(),
                        adlen as u64,
                        std::ptr::null(),
                        npub2.as_ptr(),
                        k2.as_ptr(),
                    );
                }
                eq_bytes(
                    &format!("xchacha==chacha_ietf (lib={which}, m={mlen}, ad={adlen})"),
                    &a,
                    &b,
                );
            }
        }
    }
}

/// Every AEAD `_keygen` is deterministic under the installed RNG.
#[test]
fn aead_keygens() {
    setup();
    let mut names: Vec<String> = AEADS.iter().map(|p| format!("{p}_keygen")).collect();
    names.push("crypto_aead_aes256gcm_keygen".into());
    for name in &names {
        let p = name.trim_end_matches("_keygen");
        let kb = unsafe { sym::<unsafe extern "C" fn() -> usize>(c_lib(), &format!("{p}_keybytes"))() };
        let (c, r) = pair::<Keygen>(name);
        for seed in 0..8u64 {
            let mut a = canary(kb + 8);
            let mut b = canary(kb + 8);
            reset_rngs(0xD000 + seed);
            unsafe { c(a.as_mut_ptr()) };
            reset_rngs(0xD000 + seed);
            unsafe { r(b.as_mut_ptr()) };
            eq_bytes(&format!("{name} seed={seed}"), &a, &b);
            assert_eq!(&a[kb..], &[0xA5u8; 8], "{name} wrote past keybytes");
        }
    }
}

// ---------------------------------------------------------------------------
// aes256gcm — unavailable in this build. Every operation must reject the same
// way in C and Rust (errno included).
// ---------------------------------------------------------------------------

type Beforenm = unsafe extern "C" fn(*mut u8, *const u8) -> i32;
type EncAfternm = unsafe extern "C" fn(
    *mut u8,
    *mut u64,
    *const u8,
    u64,
    *const u8,
    u64,
    *const u8,
    *const u8,
    *const u8,
) -> i32;

#[test]
fn aes256gcm_is_unavailable_identically() {
    setup();
    let mut rng = Rng::new(0x800A);
    let (cav, rav) = pair::<unsafe extern "C" fn() -> i32>("crypto_aead_aes256gcm_is_available");
    let (a, b) = unsafe { (cav(), rav()) };
    eq_i32("crypto_aead_aes256gcm_is_available", a, b);
    assert_eq!(a, 0, "this build must not have AES-NI AES-GCM");

    let s = sizes("crypto_aead_aes256gcm");
    assert_eq!((s.kb, s.nb, s.ab, s.nsb), (32, 12, 16, 0));

    let statebytes = unsafe {
        sym::<unsafe extern "C" fn() -> usize>(c_lib(), "crypto_aead_aes256gcm_statebytes")()
    };
    assert_eq!(statebytes, 512);

    let (ce, re) = pair::<Enc>("crypto_aead_aes256gcm_encrypt");
    let (cd, rd) = pair::<Dec>("crypto_aead_aes256gcm_decrypt");
    let (ced, red) = pair::<EncDet>("crypto_aead_aes256gcm_encrypt_detached");
    let (cdd, rdd) = pair::<DecDet>("crypto_aead_aes256gcm_decrypt_detached");
    let (cbn, rbn) = pair::<Beforenm>("crypto_aead_aes256gcm_beforenm");

    for &mlen in &[0usize, 16, 17, 100] {
        for &adlen in &[0usize, 16, 100] {
            let k = rng.bytes(32);
            let npub = rng.bytes(12);
            let m = rng.bytes(mlen);
            let ad = rng.bytes(adlen);

            for null_len in [false, true] {
                let mut c1 = canary(mlen + 16);
                let mut c2 = canary(mlen + 16);
                let mut l1 = 0xDEAD_BEEFu64;
                let mut l2 = 0xDEAD_BEEFu64;
                let lp1 = if null_len { std::ptr::null_mut() } else { &raw mut l1 };
                let lp2 = if null_len { std::ptr::null_mut() } else { &raw mut l2 };
                unsafe {
                    let a = ce(
                        c1.as_mut_ptr(), lp1, m.as_ptr(), mlen as u64,
                        ad.as_ptr(), adlen as u64, std::ptr::null(),
                        npub.as_ptr(), k.as_ptr(),
                    );
                    let b = re(
                        c2.as_mut_ptr(), lp2, m.as_ptr(), mlen as u64,
                        ad.as_ptr(), adlen as u64, std::ptr::null(),
                        npub.as_ptr(), k.as_ptr(),
                    );
                    eq_i32("aes256gcm_encrypt rc", a, b);
                    assert_eq!(a, -1);
                }
                eq_bytes("aes256gcm_encrypt out untouched", &c1, &c2);
                assert_eq!(c1, canary(mlen + 16));
                eq_usize("aes256gcm_encrypt *clen_p untouched", l1 as usize, l2 as usize);

                let mut m1 = canary(mlen.max(1));
                let mut m2 = canary(mlen.max(1));
                let mut o1 = 0xDEAD_BEEFu64;
                let mut o2 = 0xDEAD_BEEFu64;
                let op1 = if null_len { std::ptr::null_mut() } else { &raw mut o1 };
                let op2 = if null_len { std::ptr::null_mut() } else { &raw mut o2 };
                unsafe {
                    let a = cd(
                        m1.as_mut_ptr(), op1, std::ptr::null_mut(), c1.as_ptr(),
                        (mlen + 16) as u64, ad.as_ptr(), adlen as u64,
                        npub.as_ptr(), k.as_ptr(),
                    );
                    let b = rd(
                        m2.as_mut_ptr(), op2, std::ptr::null_mut(), c1.as_ptr(),
                        (mlen + 16) as u64, ad.as_ptr(), adlen as u64,
                        npub.as_ptr(), k.as_ptr(),
                    );
                    eq_i32("aes256gcm_decrypt rc", a, b);
                    assert_eq!(a, -1);
                }
                eq_bytes("aes256gcm_decrypt out untouched", &m1, &m2);
                eq_usize("aes256gcm_decrypt *mlen_p untouched", o1 as usize, o2 as usize);

                // detached
                let mut d1 = canary(mlen.max(1));
                let mut d2 = canary(mlen.max(1));
                let mut t1 = canary(16);
                let mut t2 = canary(16);
                let mut ml1 = 0xDEAD_BEEFu64;
                let mut ml2 = 0xDEAD_BEEFu64;
                let mp1 = if null_len { std::ptr::null_mut() } else { &raw mut ml1 };
                let mp2 = if null_len { std::ptr::null_mut() } else { &raw mut ml2 };
                unsafe {
                    let a = ced(
                        d1.as_mut_ptr(), t1.as_mut_ptr(), mp1, m.as_ptr(), mlen as u64,
                        ad.as_ptr(), adlen as u64, std::ptr::null(),
                        npub.as_ptr(), k.as_ptr(),
                    );
                    let b = red(
                        d2.as_mut_ptr(), t2.as_mut_ptr(), mp2, m.as_ptr(), mlen as u64,
                        ad.as_ptr(), adlen as u64, std::ptr::null(),
                        npub.as_ptr(), k.as_ptr(),
                    );
                    eq_i32("aes256gcm_encrypt_detached rc", a, b);
                    assert_eq!(a, -1);
                }
                eq_bytes("aes256gcm det c untouched", &d1, &d2);
                eq_bytes("aes256gcm det mac untouched", &t1, &t2);
                eq_usize("aes256gcm det *maclen_p", ml1 as usize, ml2 as usize);

                let mut p1 = canary(mlen.max(1));
                let mut p2 = canary(mlen.max(1));
                let mac = rng.bytes(16);
                unsafe {
                    let a = cdd(
                        p1.as_mut_ptr(), std::ptr::null_mut(), d1.as_ptr(), mlen as u64,
                        mac.as_ptr(), ad.as_ptr(), adlen as u64, npub.as_ptr(), k.as_ptr(),
                    );
                    let b = rdd(
                        p2.as_mut_ptr(), std::ptr::null_mut(), d1.as_ptr(), mlen as u64,
                        mac.as_ptr(), ad.as_ptr(), adlen as u64, npub.as_ptr(), k.as_ptr(),
                    );
                    eq_i32("aes256gcm_decrypt_detached rc", a, b);
                    assert_eq!(a, -1);
                }
                eq_bytes("aes256gcm det decrypt out untouched", &p1, &p2);

                // m == NULL on decrypt_detached
                unsafe {
                    let a = cdd(
                        std::ptr::null_mut(), std::ptr::null_mut(), d1.as_ptr(), mlen as u64,
                        mac.as_ptr(), ad.as_ptr(), adlen as u64, npub.as_ptr(), k.as_ptr(),
                    );
                    let b = rdd(
                        std::ptr::null_mut(), std::ptr::null_mut(), d1.as_ptr(), mlen as u64,
                        mac.as_ptr(), ad.as_ptr(), adlen as u64, npub.as_ptr(), k.as_ptr(),
                    );
                    eq_i32("aes256gcm_decrypt_detached m=NULL rc", a, b);
                }
            }
        }
    }

    // beforenm
    let k = rng.bytes(32);
    let mut st1 = State::new(statebytes);
    let mut st2 = State::new(statebytes);
    unsafe {
        let a = cbn(st1.as_mut_ptr(), k.as_ptr());
        let b = rbn(st2.as_mut_ptr(), k.as_ptr());
        eq_i32("aes256gcm_beforenm rc", a, b);
        assert_eq!(a, -1);
    }
    eq_bytes("aes256gcm_beforenm state untouched", st1.bytes(), st2.bytes());

    // *_afternm forms
    for name in [
        "crypto_aead_aes256gcm_encrypt_afternm",
        "crypto_aead_aes256gcm_decrypt_afternm",
        "crypto_aead_aes256gcm_encrypt_detached_afternm",
        "crypto_aead_aes256gcm_decrypt_detached_afternm",
    ] {
        let (c, r) = pair::<EncAfternm>(name);
        for &mlen in &[0usize, 16, 100] {
            for &adlen in &[0usize, 16] {
                let m = rng.bytes(mlen);
                let ad = rng.bytes(adlen);
                let npub = rng.bytes(12);
                let mut out1 = canary(mlen + 32);
                let mut out2 = canary(mlen + 32);
                let mut l1 = 0xDEADu64;
                let mut l2 = 0xDEADu64;
                unsafe {
                    let a = c(
                        out1.as_mut_ptr(), &mut l1, m.as_ptr(), mlen as u64,
                        ad.as_ptr(), adlen as u64, std::ptr::null(),
                        npub.as_ptr(), st1.as_ptr(),
                    );
                    let b = r(
                        out2.as_mut_ptr(), &mut l2, m.as_ptr(), mlen as u64,
                        ad.as_ptr(), adlen as u64, std::ptr::null(),
                        npub.as_ptr(), st2.as_ptr(),
                    );
                    eq_i32(&format!("{name} rc"), a, b);
                    assert_eq!(a, -1, "{name} must be unavailable");
                }
                eq_bytes(&format!("{name} out untouched"), &out1, &out2);
                eq_usize(&format!("{name} *len untouched"), l1 as usize, l2 as usize);
            }
        }
    }
}

/// CONFIGS G3-100 — the original (8-byte-nonce) and IETF (12-byte-nonce)
/// chacha20poly1305 constructions differ in nonce length, AD padding and the
/// order of the length fields, so a ciphertext produced by one must NOT verify
/// under the other. Both libraries must reject in exactly the same way.
#[test]
fn chacha20poly1305_variants_are_not_interchangeable() {
    setup();
    let mut rng = Rng::new(0x800B);
    let (ce_ietf, _) = pair::<Enc>("crypto_aead_chacha20poly1305_ietf_encrypt");
    let (ce_orig, _) = pair::<Enc>("crypto_aead_chacha20poly1305_encrypt");
    let (cd_ietf, rd_ietf) = pair::<Dec>("crypto_aead_chacha20poly1305_ietf_decrypt");
    let (cd_orig, rd_orig) = pair::<Dec>("crypto_aead_chacha20poly1305_decrypt");

    for &mlen in &[0usize, 1, 16, 17, 64, 100] {
        for &adlen in &[0usize, 16, 17] {
            let k = rng.bytes(32);
            // a 12-byte nonce whose first 8 bytes double as the original
            // variant's nonce
            let n12 = rng.bytes(12);
            let m = rng.bytes(mlen);
            let ad = rng.bytes(adlen);

            // encrypt with IETF, try to decrypt with the original variant
            let mut c = canary(mlen + 16);
            unsafe {
                ce_ietf(
                    c.as_mut_ptr(), std::ptr::null_mut(), m.as_ptr(), mlen as u64,
                    ad.as_ptr(), adlen as u64, std::ptr::null(), n12.as_ptr(), k.as_ptr(),
                );
            }
            let mut o1 = canary(mlen.max(1));
            let mut o2 = canary(mlen.max(1));
            let mut l1 = 0xDEADu64;
            let mut l2 = 0xDEADu64;
            let (a, b) = unsafe {
                (
                    cd_orig(o1.as_mut_ptr(), &mut l1, std::ptr::null_mut(), c.as_ptr(),
                            (mlen + 16) as u64, ad.as_ptr(), adlen as u64, n12.as_ptr(), k.as_ptr()),
                    rd_orig(o2.as_mut_ptr(), &mut l2, std::ptr::null_mut(), c.as_ptr(),
                            (mlen + 16) as u64, ad.as_ptr(), adlen as u64, n12.as_ptr(), k.as_ptr()),
                )
            };
            eq_i32("ietf ct under original decrypt rc", a, b);
            eq_usize("ietf ct under original decrypt *mlen_p", l1 as usize, l2 as usize);
            eq_bytes("ietf ct under original decrypt m", &o1, &o2);

            // encrypt with the original variant, try to decrypt with IETF
            let mut c = canary(mlen + 16);
            unsafe {
                ce_orig(
                    c.as_mut_ptr(), std::ptr::null_mut(), m.as_ptr(), mlen as u64,
                    ad.as_ptr(), adlen as u64, std::ptr::null(), n12.as_ptr(), k.as_ptr(),
                );
            }
            let mut o1 = canary(mlen.max(1));
            let mut o2 = canary(mlen.max(1));
            let mut l1 = 0xDEADu64;
            let mut l2 = 0xDEADu64;
            let (a, b) = unsafe {
                (
                    cd_ietf(o1.as_mut_ptr(), &mut l1, std::ptr::null_mut(), c.as_ptr(),
                            (mlen + 16) as u64, ad.as_ptr(), adlen as u64, n12.as_ptr(), k.as_ptr()),
                    rd_ietf(o2.as_mut_ptr(), &mut l2, std::ptr::null_mut(), c.as_ptr(),
                            (mlen + 16) as u64, ad.as_ptr(), adlen as u64, n12.as_ptr(), k.as_ptr()),
                )
            };
            eq_i32("original ct under ietf decrypt rc", a, b);
            eq_usize("original ct under ietf decrypt *mlen_p", l1 as usize, l2 as usize);
            eq_bytes("original ct under ietf decrypt m", &o1, &o2);
        }
    }
}

/// CONFIGS G3-131 / G3-132 / G3-133 / G3-134 — cross-primitive invariants:
/// tag placement, the five distinct `messagebytes_max` values, `nsecbytes == 0`
/// everywhere, and the ABYTES split (32 for AEGIS -> `crypto_verify_32`,
/// 16 for the poly1305 variants -> `crypto_verify_16`).
#[test]
fn aead_cross_primitive_invariants() {
    setup();
    let expect: &[(&str, usize, usize, usize, usize, u64)] = &[
        // (prefix, keybytes, npubbytes, abytes, nsecbytes, messagebytes_max)
        ("crypto_aead_aegis128l", 16, 16, 32, 0, 2305843009213693951),
        ("crypto_aead_aegis256", 32, 32, 32, 0, 2305843009213693951),
        ("crypto_aead_chacha20poly1305", 32, 8, 16, 0, 18446744073709551599),
        ("crypto_aead_chacha20poly1305_ietf", 32, 12, 16, 0, 274877906880),
        ("crypto_aead_xchacha20poly1305_ietf", 32, 24, 16, 0, 18446744073709551599),
        ("crypto_aead_aes256gcm", 32, 12, 16, 0, 68719476704),
    ];
    for &(p, kb, nb, ab, nsb, max) in expect {
        let s = sizes(p);
        assert_eq!((s.kb, s.nb, s.ab, s.nsb), (kb, nb, ab, nsb), "{p} sizes");
        assert_eq!(s.max, max, "{p}_messagebytes_max");
        // and the Rust library must report exactly the same
        let g = |lib: &'static libloading::Library, n: &str| -> usize {
            unsafe { sym::<unsafe extern "C" fn() -> usize>(lib, &format!("{p}_{n}"))() }
        };
        let gm = |lib: &'static libloading::Library| -> u64 {
            unsafe { sym::<unsafe extern "C" fn() -> u64>(lib, &format!("{p}_messagebytes_max"))() }
        };
        for n in ["keybytes", "npubbytes", "abytes", "nsecbytes"] {
            assert_eq!(g(c_lib(), n), g(r_lib(), n), "{p}_{n}");
        }
        assert_eq!(gm(c_lib()), gm(r_lib()), "{p}_messagebytes_max");
    }
    // the five available primitives split 2/3 on tag length
    let ab32: Vec<&str> = AEADS.iter().copied().filter(|p| sizes(p).ab == 32).collect();
    let ab16: Vec<&str> = AEADS.iter().copied().filter(|p| sizes(p).ab == 16).collect();
    assert_eq!(ab32.len(), 2, "two AEGIS primitives use a 32-byte tag");
    assert_eq!(ab16.len(), 3, "three poly1305 primitives use a 16-byte tag");

    // CONFIGS G3-128 — the aesni / armcrypto aes256gcm translation units are
    // compiled but wholly `#ifdef`-ed out, so they contribute NO symbols to
    // either build. Every aes256gcm entry point comes from the stub block.
    for lib in [c_lib(), r_lib()] {
        for name in [
            "crypto_aead_aes256gcm_encrypt_aesni",
            "crypto_aead_aes256gcm_encrypt_armcrypto",
            "aead_aes256gcm_aesni_implementation",
            "aead_aes256gcm_armcrypto_implementation",
        ] {
            assert!(
                unsafe { lib.get::<*const std::ffi::c_void>(name.as_bytes()) }.is_err(),
                "{name} must not be exported"
            );
        }
        // ...while the stub-provided entry points ARE all present
        for name in [
            "crypto_aead_aes256gcm_encrypt",
            "crypto_aead_aes256gcm_decrypt",
            "crypto_aead_aes256gcm_encrypt_detached",
            "crypto_aead_aes256gcm_decrypt_detached",
            "crypto_aead_aes256gcm_beforenm",
            "crypto_aead_aes256gcm_encrypt_afternm",
            "crypto_aead_aes256gcm_decrypt_afternm",
            "crypto_aead_aes256gcm_encrypt_detached_afternm",
            "crypto_aead_aes256gcm_decrypt_detached_afternm",
            "crypto_aead_aes256gcm_is_available",
        ] {
            assert!(
                unsafe { lib.get::<*const std::ffi::c_void>(name.as_bytes()) }.is_ok(),
                "{name} must be exported"
            );
        }
    }
}
